B=[
dict(a=1,z=3,star=3,lit=L(1,3),
key=[('登基','H7225','bereshit','開始'),('站在','H5975','amod','站立'),('一字不可刪減','H1639','tigra','減少'),('或者','H194','ulai','或許'),('後悔','H5162','venikhamti','後悔、改變心意'),('回頭','H7725','veyashuvu','回轉')],
gram=['**{H1639}**（gara，刪減）：神說「**一字不可刪減**」。意思是：**不增加，也不減少**。先知的職事，不是創作，而是**忠實的傳遞**。','**{H5162}**（nakham，後悔）：「使我**後悔**」。這個字也出現在十八章8節。**神的話對人的回應是活的：人若回頭，神所說要降的災，就不成就。**這是神的心意——**審判的目的是挽回。**'],
exp=['二十六章的時間點，是**約雅敬登基的時候**（主前609年左右），比二十五章的「第四年」更早。這一章，與**七章的殿中講章**相呼應：**七章是講章的內容，二十六章是講章之後發生的事。**所以請你把七章和二十六章**放在一起讀**：先聽講章，再看人怎樣回應。','神的吩咐很具體：**你站在耶和華殿的院內，對猶大眾城邑的人，就是到耶和華殿來禮拜的，說我所吩咐你的一切話，一字不可刪減。**請留意：**場合是殿院，聽眾是來禮拜的人。**神把最難聽的話，放在**最神聖的地方**說。這不是偶然：**最需要聽見的人，正是以為自己最安全的人。**','三節的「**或者**」兩個字，很值得停下來。**神是無所不知的，可是祂仍然說「或者他們肯聽從」。**這表示：**神的呼召是真誠的，門真的是開著的。**先知的任務，不是宣判一個已經決定的結局，而是**把一扇真實的門，指給人看。**']),
dict(a=4,z=6,star=3,lit=L(4,6),
key=[('律法','H8451','torati','妥拉、指示'),('從早起來','H7925','vehashkem','清早起來'),('僕人眾先知','H5650','avadai','僕人'),('示羅','H7887','shiloh','示羅（地名）'),('咒詛','H7045','liqelalah','咒詛'),('殿','H1004','habayit','殿、家')],
gram=['**{H7887}**（Shiloh，示羅）：這裡的「示羅」，是**以色列人從前安放約櫃的地方**（撒上四章）。**示羅曾經是神的居所，後來被毀**（詩七十八60）。神說：**這殿也可以像示羅。**','**{H7925}**（shakham，從早起來）：與二十五章3、4節**同一個字**。**神從早起來差遣先知，是神耐心的記號。**'],
exp=['四至六節是**講章的核心**，只有兩個條件、一個後果：**若不聽從，不遵行我的律法，不聽僕人眾先知的話，我就必使這殿如示羅。**請留意：**神不是反對殿，而是反對把殿當作護身符**（七章4節：「這些是耶和華的殿」）。**殿本身不能救人，神的話才能。**','「示羅」是**每一個以色列人都知道的歷史**：約櫃曾在那裡，後來被非利士人擄去，示羅荒廢。**神說：你們以為殿永遠不會倒，示羅也曾經以為。**這句話，**對耶路撒冷人來說，是最刺耳的一句**：因為殿，是他們**最後的安全感**。','六節的結尾：**使這城為地上萬國所咒詛的。**這是**對亞伯拉罕之約的反面**：本來，**萬國要因這城得福**（創十二3），現在，**萬國要拿這城作咒詛的例子**。**一個蒙揀選的城，若不聽神的話，會成為警戒。**']),
dict(a=7,z=9,star=3,lit=L(7,9),
key=[('祭司','H3548','hakohanim','祭司'),('先知','H5030','venenavim','先知'),('抓住','H8610','vayitpesu','抓住'),('你必要死','H4191','mot tamut','死，你必死'),('為何','H4069','maddua','為什麼'),('荒場','H2717','tekhrav','荒廢（動詞）')],
gram=['**{H8610}**（taphas，抓住）：這個字是**逮捕、抓取**。**耶利米把一切話說完了，才被抓。**他沒有刪減，也沒有因為怕而提早停下來。','**{H4069}**（maddua，為何）：「你**為何**託耶和華的名預言」。這是一個**質問**，意思是：**你憑什麼？你有什麼權柄？**'],
exp=['七至九節是**最戲劇性的一幕**：耶利米**說完了耶和華所吩咐他對眾人說的一切話**，**祭司、先知與眾民都來抓住他，說：你必要死！**請留意：**第一批動手的，是祭司和先知。**也就是**那些本來應該保護神的話的人**。**宗教領袖，常常是最先抵擋神話語的人。**','他們的控告很清楚：**你為何託耶和華的名預言，說這殿必如示羅，這城必變為荒場無人居住呢？**這是一個**按申命記十八章20節所作的控告**：**假先知必須治死。**他們以為，**自己是在保護神的殿，其實是在抵擋神的話。**','「你必要死」這句話，**在耶穌受審的夜晚，也出現過**：大祭司和公會說：**他是該死的**（馬太福音二十六章66節）。**同樣的控告，同樣的人，同樣的殿。**耶利米在這裡，**使我們想起後來的耶穌**，**說真話，因真話被控告。**']),
dict(a=10,z=11,star=2,lit=L(10,11),
key=[('首領','H8269','sarei','官長、首領'),('新門','H8179','shaar hakhadash','新門'),('該死','H4194','mishpat mavet','死刑的判決'),('親耳所聽見','H241','beoznekhem','在你們耳中'),('王宮','H4428','melekh','王（王宮）')],
gram=['**{H4941}**（mishpat，判決）、**{H4194}**（mavet，死）：「這人是該死的」，直譯是「**這人有死刑的判決**」。**祭司、先知把這件事，說成一場法律的審判。**','**{H8179}**（shaar，門）：**「新門」是殿的一個門**，也是**審判的地方**。**首領坐在殿門口，是要開庭審判。**'],
exp=['十節是**一個很有意思的細節**：**猶大的首領聽見這事，就從王宮上到耶和華的殿，坐在新門口。**首領們**沒有立刻跟著群眾**，而是**走上殿來，按著審判的程序開庭**。**在混亂的時候，有人還記得「要按法律」。**這是**這一章第一個小小的亮光**。','十一節是**祭司、先知的控告**：這人是該死的，因為他說預言攻擊這城，**正如你們親耳所聽見的**。請留意：**他們控告的罪名，是「攻擊這城」**，也就是**他們把神的話，當作對國家的攻擊**。**這是每一個時代的先知，都要面對的控告。**']),
dict(a=12,z=13,star=3,lit=L(12,13),
key=[('耶和華差遣我','H7971','shelakhani','差遣'),('改正','H3190','heitivu','使善、改好'),('行動','H1870','darkekhem','道路'),('作為','H4611','maalleikhem','行為'),('聽從','H8085','ushmau','聽'),('後悔','H5162','venikhem','後悔')],
gram=['**{H3190}**（yatav，改正）：這個字的意思是**使它變好、改好**。**神要的，是行動作為上實際的改變**，不是一句漂亮的話。','**{H5162}**（nakham，後悔）：再一次出現。**耶利米在被控告的時刻，還在給他們一條回頭的路。**'],
exp=['耶利米的回答，是**整章最有力的一段**。他**沒有求饒，沒有辯解，也沒有改口**，他只說了兩件事：第一，**耶和華差遣我預言，攻擊這殿和這城**；第二，**現在要改正你們的行動作為，聽從耶和華你們神的話，他就必後悔，不將所說的災禍降與你們。**','請留意：**在生命受到威脅的時候，耶利米說的仍然是「回頭的路」。**他沒有因為被抓，就把信息改成咒詛。**這是**真先知的記號**：**他的心，始終是要人回來。**這與耶穌在十字架上說「父啊，赦免他們」，**是同一個心。**']),
dict(a=14,z=15,star=3,lit=L(14,15),
key=[('我在你們手中','H2005','hineni','看哪，我在這裡'),('善','H2896','ketov','好'),('正','H3477','vekhyashar','正直'),('無辜','H5355','naqi','無罪'),('血','H1818','dam','血'),('確實地知道','H3045','yado tedeu','要知道')],
gram=['**{H5355}**（naqi，無辜）：這個字的意思是**無罪的、沒有責任的**。**無辜人的血，會歸到殺他的人身上**。這是**聖經對流無辜之血的嚴肅看法**（創九6；申十九10）。','**{H1818}**（dam，血）：血在舊約，**代表生命**。**流無辜人的血，是對生命的侵犯，也是對神的侵犯。**'],
exp=['十四節是**一句很平靜的話**：**至於我，我在你們手中，你們眼看何為善，何為正，就那樣待我吧！**這不是**自暴自棄**，也不是**尋死**。這是**一個把自己交在神手中的人**，**不爭、不逃、也不懼怕**。他**知道真正的審判者是誰**。','十五節**沒有威脅，只有警告**：**但你們要確實地知道，若把我治死，就使無辜人的血歸到你們和這城。**他**沒有為自己求情，而是為這城擔心**。**他最怕的，是他們犯下更大的罪。**這就是**先知的心：連面對想殺他的人，仍然為他們著想。**']),
dict(a=16,z=16,star=3,lit=L(16,16),
key=[('首領和眾民','H8269','hasarim','首領'),('不該死','H4194','ein mishpat mavet','沒有死刑的判決'),('我們神的名','H8034','beshem eloheinu','奉我們神的名')],
gram=['**{H369}**（ayin，不）、**{H4941}**（mishpat，判決）、**{H4194}**（mavet，死）：「這人是**不該死的**」，直譯是「**這人沒有死刑的判決**」，正好**反過來**回應十一節祭司、先知的控告。','**{H8034}**（shem，名）：「他是**奉耶和華我們神的名**向我們說話」。**真先知的標準，是他奉誰的名說話。**'],
exp=['十六節是**局面的轉折**：**首領和眾民，竟然站在耶利米這一邊**，對祭司、先知說：這人是不該死的，因為他是奉耶和華我們神的名向我們說話。**宗教領袖要殺他，反而是首領和平民，聽見了神的聲音。**','這個轉折，**不是因為群眾一時心軟**，而是因為**耶利米的話，真的聽進去了**：他說的是**回頭**，不是咒詛。**真話，有時候要等到最後，才被聽見。**']),
dict(a=17,z=19,star=3,lit=L(17,19),
key=[('長老','H2205','ziqnei','長老'),('彌迦','H4318','mikhah','彌迦（人名）'),('錫安必被耕種像一塊田','H2790','tekharesh','耕、犁'),('亂堆','H5856','iyyim','廢墟、亂堆'),('敬畏','H3373','yare','敬畏'),('懇求他的恩','H2470','vaykhal','懇求')],
gram=['**{H2790}**（kharash，耕種）：「錫安必被**耕種**像一塊田」。這是**彌迦書三章12節的話**。**長老們把一位先前先知的話，當作今日的先例。**','**{H3373}**（yare，敬畏）：希西家**敬畏耶和華**，**懇求他的恩**，神就後悔。**敬畏，是回應；懇求，是回應。**'],
exp=['十七至十九節，是**長老們的回答**。他們沒有爭辯對錯，而是**講了一個歷史的先例**：希西家的日子，**摩利沙人彌迦**也說過同樣的話，錫安必被耕種像一塊田。**那時候，希西家沒有殺他，而是敬畏耶和華、懇求他的恩。****耶和華就後悔，不降災。**','請留意：**長老們用的，是聖經的先例。**他們**不是靠多數決**，而是**把今天的事，放在過去神的作為裡**。這是**每一個教會，最可靠的辨別方法之一：回到神過去怎樣對待祂的僕人。**','十九節的結尾很深：**若治死這人，我們就作了大惡，自害己命。**他們看見：**殺死先知，不是消滅了話，而是傷害了自己。**這是**一個歷史的教訓**，也是**一個今日的提醒**：**不聽神話的人，最終受傷的，是自己。**']),
dict(a=20,z=21,star=3,lit=L(20,21),
key=[('烏利亞','H223','uriyahu','（人名）耶和華是我的光'),('耶琳','H7157','qiryat yearim','基列‧耶琳（地名）'),('勇士','H1368','gibborav','勇士'),('想要把他治死','H1245','vayevaqesh','尋求'),('懼怕','H3372','vayyira','懼怕'),('逃往埃及','H1272','vayivrakh','逃跑')],
gram=['**{H3372}**（yare，懼怕）：烏利亞「聽見就**懼怕**」。**經文只記錄他的懼怕，沒有評價他。**注意：**同一個字，在十九節是「敬畏」（希西家敬畏耶和華）**，在這裡是「懼怕」（烏利亞懼怕王）。**同一個字，兩個對象。**','**{H1272}**（barakh，逃跑）：烏利亞**逃往埃及**。**埃及是人以為安全的地方**（參四十二至四十四章）。**逃跑，沒有救他。**'],
exp=['二十至二十三節，是一段**很沉重的插入**（和合本用括號標示）。**另有一位先知烏利亞，奉耶和華的名說預言，說的話和耶利米完全一樣。**約雅敬王和他眾勇士、眾首領聽見，王就想要把他治死。烏利亞**聽見就懼怕，逃往埃及去了**。','請留意：**這一段很安靜，沒有評價**。經文**沒有說烏利亞軟弱，也沒有說他不信**。**一個人面對王的死亡威脅，會害怕，這是很人性的反應。**我們讀這段話，**不要輕易責備他**。**聖經記載他，是為了讓我們看見：說真話的代價，是真實的。**']),
dict(a=22,z=23,star=2,lit=L(22,23),
key=[('以利拿單','H494','elnatan','（人名）神賜'),('亞革波','H5907','akhbor','（人名）'),('帶出來','H3318','vayotsiu','帶出'),('用刀殺了他','H5221','vayakehu','擊殺'),('屍首','H5038','nivlato','屍體'),('平民的墳地','H6913','qivrei','墳墓')],
gram=['**{H494}**（Elnatan，以利拿單）：這位被王差去捉人的**以利拿單**，後來在**三十六章**，**竟然是勸王不要燒書卷的人之一**（36:25）。**人，是會改變的。**','**{H5038}**（nevelah，屍首）：「把他的屍首拋在**平民的墳地**中」。**他不只被殺，還被羞辱。**這是**對先知的極大侮辱**。'],
exp=['二十二、二十三節很殘酷：**約雅敬王便打發亞革波的兒子以利拿單，帶領幾個人往埃及去。他們就從埃及將烏利亞帶出來，送到約雅敬王那裡；王用刀殺了他，把他的屍首拋在平民的墳地中。****逃到埃及，也沒有逃過。**王的手，伸得很長。','這一段，與下一節**形成強烈的對比**：**同樣是說預言的先知，一位被殺，一位被保護。**我們不要急著解釋。**聖經沒有解釋，我們也不能代替神解釋。**我們只能**誠實地承認**：**神的僕人，有不同的結局。**（議題另述）']),
dict(a=24,z=24,star=3,lit=L(24,24),
key=[('亞希甘','H296','akhiqam','（人名）我兄弟起來'),('沙番','H8227','shafan','（人名）'),('治死','H4191','lehamito','使死'),('百姓的手','H5971','haam','百姓')],
gram=['**{H296}**（Akhiqam，亞希甘）：這個名字的意思是「**我的兄弟起來**」。**亞希甘的家族，後來一直保護先知**：他的兒子基大利，後來成為猶大的省長（三十九14；四十5）。','**{H8227}**（Shafan，沙番）：**沙番是約西亞王時代的書記**（王下二十二章）。**這個家族，是一個尊重神話語的家族。**'],
exp=['二十四節**只有一句話**，卻是**整章的結尾，也是整章的轉折**：**然而，沙番的兒子亞希甘保護耶利米，不交在百姓的手中治死他。**請留意：**保護耶利米的，不是天使，也不是神蹟，而是一位有影響力的人。**神常常用**人的手**，作祂保護的方式。','這一節提醒我們：**神的保護，常常藏在一個普通的名字背後。**亞希甘沒有講道，沒有預言，**他只是在關鍵的時刻，站了出來**。**一個人的勇氣，可以救一位先知。**同時，**這也讓我們謙卑：烏利亞沒有亞希甘。**這就是**這一章留給我們的問題**，也是**我們需要安靜的地方**。']),
]
